/**
 * Object storage port (ADR 0007). Features store object **keys** only; the
 * public URL is derived from configuration, so moving to another provider is
 * a configuration change plus copying the objects.
 */
export interface PutObjectInput {
  /** Generated by the API, never taken from a client. */
  key: string;
  body: Buffer;
  contentType: string;
  /** Keys are immutable (a new upload gets a new key), so caching is long. */
  cacheControl: string;
}

export abstract class ObjectStorage {
  abstract put(input: PutObjectInput): Promise<void>;

  /** Deletes objects; keys that do not exist are ignored. */
  abstract delete(keys: readonly string[]): Promise<void>;

  /** Public URL of an object in the public bucket. */
  abstract publicUrl(key: string): string;
}

/** The storage provider failed or could not be reached. Never carries keys or credentials. */
export class StorageUnavailableError extends Error {
  override readonly name = 'StorageUnavailableError';
}

/** Cache header for immutable public images. */
export const IMMUTABLE_CACHE_CONTROL = 'public, max-age=31536000, immutable';

/** `base` + `/` + each key segment URL-encoded. */
export function joinPublicUrl(base: string, key: string): string {
  const prefix = base.endsWith('/') ? base.slice(0, -1) : base;
  return `${prefix}/${key.split('/').map(encodeURIComponent).join('/')}`;
}
